INSERT INTO `sanpham` (`id`, `ten`, `loai`, `gia`, `gia_cu`, `so_luong_ton`, `mo_ta`, `tao_luc`, `cap_nhat_luc`) VALUES ('03c18bcf-b31f-4477-ad1d-692d4ef50d65','Gọng kính AVERY SAMI','gong',760000.00,NULL,19,'<p class=\"ql-align-center\"><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">🌼&nbsp;Đa&nbsp;giác&nbsp;phá&nbsp;cách,&nbsp;chất&nbsp;riêng&nbsp;bứt&nbsp;phá&nbsp;🌼</strong></p><p class=\"ql-align-center\"><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Gọng&nbsp;kính&nbsp;nhựa&nbsp;kết&nbsp;hợp&nbsp;kim&nbsp;loại&nbsp;form&nbsp;đa&nbsp;giác&nbsp;là&nbsp;một&nbsp;trong&nbsp;những&nbsp;xu&nbsp;hướng&nbsp;thiết&nbsp;kế&nbsp;độc&nbsp;đáo&nbsp;và&nbsp;hiện&nbsp;đại&nbsp;nhất&nbsp;hiện&nbsp;nay</span></p><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Chi&nbsp;tiết&nbsp;chất&nbsp;liệu&nbsp;&amp;&nbsp;cấu&nbsp;trúc:</strong></p><ul><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Phần&nbsp;gọng&nbsp;trước&nbsp;(mặt&nbsp;kính):</span><ul><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Chất&nbsp;liệu:&nbsp;được&nbsp;làm&nbsp;từ&nbsp;nhựa,&nbsp;giúp&nbsp;định&nbsp;hình&nbsp;rõ&nbsp;nét&nbsp;các&nbsp;góc&nbsp;cạnh&nbsp;của&nbsp;dáng&nbsp;đa&nbsp;giác.&nbsp;Chất&nbsp;liệu&nbsp;nhựa&nbsp;cho&nbsp;phép&nbsp;đa&nbsp;dạng&nbsp;về&nbsp;màu&nbsp;sắc&nbsp;và&nbsp;hoa&nbsp;văn,&nbsp;từ&nbsp;các&nbsp;tông&nbsp;màu&nbsp;trơn&nbsp;lì,&nbsp;trong&nbsp;suốt,&nbsp;bán&nbsp;trong&nbsp;suốt&nbsp;đến&nbsp;họa&nbsp;tiết&nbsp;đồi&nbsp;mồi</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Dáng&nbsp;đa&nbsp;giác:&nbsp;Đây&nbsp;là&nbsp;điểm&nbsp;nhấn&nbsp;chính.&nbsp;Các&nbsp;cạnh&nbsp;của&nbsp;gọng&nbsp;được&nbsp;cắt&nbsp;gọt&nbsp;tinh&nbsp;xảo,&nbsp;tạo&nbsp;nên&nbsp;các&nbsp;góc&nbsp;nhọn&nbsp;hoặc&nbsp;bo&nbsp;tròn&nbsp;nhẹ&nbsp;tùy&nbsp;theo&nbsp;từng&nbsp;thiết&nbsp;kế&nbsp;cụ&nbsp;thể.&nbsp;Dáng&nbsp;này&nbsp;phá&nbsp;vỡ&nbsp;sự&nbsp;truyền&nbsp;thống&nbsp;của&nbsp;gọng&nbsp;tròn&nbsp;hay&nbsp;vuông,&nbsp;mang&nbsp;đến&nbsp;sự&nbsp;khác&nbsp;biệt&nbsp;và&nbsp;phá&nbsp;cách.</span></li></ul></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Phần&nbsp;cầu&nbsp;kính&nbsp;và&nbsp;càng&nbsp;kính:</span><ul><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Chất&nbsp;liệu&nbsp;kim&nbsp;loại:&nbsp;Đây&nbsp;là&nbsp;nơi&nbsp;chất&nbsp;liệu&nbsp;kim&nbsp;loại&nbsp;được&nbsp;ứng&nbsp;dụng&nbsp;để&nbsp;tạo&nbsp;sự&nbsp;thanh&nbsp;thoát&nbsp;và&nbsp;tinh&nbsp;tế.</span><ul><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Cầu&nbsp;kính:&nbsp;là&nbsp;một&nbsp;thanh&nbsp;kim&nbsp;loại&nbsp;mảnh,&nbsp;nối&nbsp;liền&nbsp;hai&nbsp;mắt&nbsp;kính,&nbsp;tạo&nbsp;cảm&nbsp;giác&nbsp;nhẹ&nbsp;nhàng&nbsp;và&nbsp;&quot;bay&nbsp;bổng&quot;&nbsp;cho&nbsp;tổng&nbsp;thể</span></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Càng&nbsp;kính:&nbsp;Thường&nbsp;được&nbsp;làm&nbsp;bằng&nbsp;kim&nbsp;loại,&nbsp;mang&nbsp;lại&nbsp;vẻ&nbsp;thanh&nbsp;lịch&nbsp;và&nbsp;hiện&nbsp;đại.&nbsp;Càng&nbsp;kim&nbsp;loại&nbsp;có&nbsp;thể&nbsp;rất&nbsp;mảnh&nbsp;mai,&nbsp;thuôn&nbsp;dài,&nbsp;hoặc&nbsp;có&nbsp;các&nbsp;chi&nbsp;tiết&nbsp;chạm&nbsp;khắc,&nbsp;vân&nbsp;nổi&nbsp;để&nbsp;tăng&nbsp;thêm&nbsp;điểm&nbsp;nhấn.&nbsp;Phần&nbsp;đuôi&nbsp;càng&nbsp;thường&nbsp;được&nbsp;bọc&nbsp;một&nbsp;lớp&nbsp;nhựa&nbsp;hoặc&nbsp;silicone&nbsp;mềm&nbsp;mại&nbsp;để&nbsp;tạo&nbsp;sự&nbsp;thoải&nbsp;mái&nbsp;khi&nbsp;đeo.</span></li></ul></li><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Mối&nbsp;nối/Bản&nbsp;lề:&nbsp;Sự&nbsp;chuyển&nbsp;tiếp&nbsp;giữa&nbsp;gọng&nbsp;nhựa&nbsp;và&nbsp;càng&nbsp;kim&nbsp;loại&nbsp;được&nbsp;thiết&nbsp;kế&nbsp;rất&nbsp;tỉ&nbsp;mỉ.&nbsp;Đó&nbsp;có&nbsp;thể&nbsp;là&nbsp;một&nbsp;khớp&nbsp;nối&nbsp;ẩn&nbsp;để&nbsp;tạo&nbsp;sự&nbsp;liền&nbsp;mạch,&nbsp;hoặc&nbsp;bản&nbsp;lề&nbsp;lộ&nbsp;thiên&nbsp;với&nbsp;các&nbsp;chi&nbsp;tiết&nbsp;kim&nbsp;loại,&nbsp;đinh&nbsp;tán&nbsp;(rivets)&nbsp;nổi&nbsp;bật,&nbsp;làm&nbsp;tăng&nbsp;thêm&nbsp;vẻ&nbsp;công&nbsp;nghiệp,&nbsp;cổ&nbsp;điển&nbsp;hoặc&nbsp;sang&nbsp;trọng&nbsp;cho&nbsp;thiết&nbsp;kế</span></li></ul></li></ul><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Dưới&nbsp;đây&nbsp;là&nbsp;các&nbsp;bước&nbsp;và&nbsp;lưu&nbsp;ý&nbsp;chi&nbsp;tiết&nbsp;về&nbsp;cách&nbsp;bảo&nbsp;quản&nbsp;gọng&nbsp;kính&nbsp;nhựa&nbsp;kết&nbsp;hợp&nbsp;kim&nbsp;loại:</strong></p><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">1.&nbsp;Vệ&nbsp;sinh&nbsp;kính&nbsp;thường&nbsp;xuyên&nbsp;và&nbsp;đúng&nbsp;cách:</strong></p><ul><li><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Sử&nbsp;dụng&nbsp;khăn&nbsp;và&nbsp;nước&nbsp;lau&nbsp;kính&nbsp;chuyên&nbsp;dụng&nbsp;được&nbsp;tặng&nbsp;kem&nbsp;khi&nbsp;lắp&nbsp;kính&nbsp;tại&nbsp;GlassyZone&nbsp;</span></li></ul><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">2.&nbsp;Tránh&nbsp;nhiệt&nbsp;độ&nbsp;cao&nbsp;và&nbsp;thay&nbsp;đổi&nbsp;nhiệt&nbsp;độ&nbsp;đột&nbsp;ngột:</strong></p><ul><li><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Tránh&nbsp;ánh&nbsp;nắng&nbsp;trực&nbsp;tiếp:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;Không&nbsp;để&nbsp;kính&nbsp;trong&nbsp;xe&nbsp;hơi&nbsp;dưới&nbsp;trời&nbsp;nắng&nbsp;gắt,&nbsp;gần&nbsp;bếp,&nbsp;lò&nbsp;sưởi&nbsp;hoặc&nbsp;các&nbsp;nguồn&nbsp;nhiệt&nbsp;độ&nbsp;cao&nbsp;khác.&nbsp;Nhiệt&nbsp;độ&nbsp;cao&nbsp;có&nbsp;thể&nbsp;làm&nbsp;biến&nbsp;dạng&nbsp;gọng&nbsp;nhựa,&nbsp;bong&nbsp;tróc&nbsp;lớp&nbsp;phủ&nbsp;tròng&nbsp;kính,&nbsp;và&nbsp;ảnh&nbsp;hưởng&nbsp;đến&nbsp;độ&nbsp;bền&nbsp;của&nbsp;kim&nbsp;loại.</span></li></ul><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">3.&nbsp;Đeo&nbsp;và&nbsp;tháo&nbsp;kính&nbsp;đúng&nbsp;cách:</strong></p><ul><li><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Dùng&nbsp;cả&nbsp;hai&nbsp;tay:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;Luôn&nbsp;dùng&nbsp;cả&nbsp;hai&nbsp;tay&nbsp;để&nbsp;đeo&nbsp;và&nbsp;tháo&nbsp;kính.&nbsp;Việc&nbsp;dùng&nbsp;một&nbsp;tay&nbsp;có&nbsp;thể&nbsp;làm&nbsp;cong&nbsp;vênh&nbsp;gọng&nbsp;kính,&nbsp;lỏng&nbsp;ốc&nbsp;vít&nbsp;ở&nbsp;các&nbsp;khớp&nbsp;nối,&nbsp;đặc&nbsp;biệt&nbsp;là&nbsp;với&nbsp;gọng&nbsp;kết&nbsp;hợp&nbsp;kim&nbsp;loại.</span></li><li><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Không&nbsp;đẩy&nbsp;kính&nbsp;lên&nbsp;đầu:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;Tránh&nbsp;đẩy&nbsp;kính&nbsp;lên&nbsp;tóc&nbsp;hoặc&nbsp;đỉnh&nbsp;đầu&nbsp;vì&nbsp;điều&nbsp;này&nbsp;có&nbsp;thể&nbsp;làm&nbsp;giãn&nbsp;gọng,&nbsp;thay&nbsp;đổi&nbsp;form&nbsp;kính&nbsp;và&nbsp;làm&nbsp;lỏng&nbsp;khớp.</span></li></ul><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">4.&nbsp;Cất&nbsp;giữ&nbsp;kính&nbsp;đúng&nbsp;nơi:</strong></p><ul><li><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Sử&nbsp;dụng&nbsp;hộp&nbsp;đựng&nbsp;kính:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;Luôn&nbsp;cất&nbsp;kính&nbsp;trong&nbsp;hộp&nbsp;cứng&nbsp;khi&nbsp;không&nbsp;sử&nbsp;dụng,&nbsp;đặc&nbsp;biệt&nbsp;khi&nbsp;di&nbsp;chuyển&nbsp;hoặc&nbsp;để&nbsp;trong&nbsp;túi&nbsp;xách&nbsp;để&nbsp;tránh&nbsp;va&nbsp;đập,&nbsp;trầy&nbsp;xước&nbsp;và&nbsp;đè&nbsp;nén.</span></li><li><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Để&nbsp;kính&nbsp;úp&nbsp;mặt&nbsp;kính&nbsp;xuống&nbsp;hoặc&nbsp;gập&nbsp;gọn:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;Nếu&nbsp;không&nbsp;có&nbsp;hộp,&nbsp;hãy&nbsp;gập&nbsp;gọn&nbsp;càng&nbsp;kính&nbsp;và&nbsp;đặt&nbsp;kính&nbsp;úp&nbsp;mặt&nbsp;tròng&nbsp;kính&nbsp;xuống&nbsp;(trên&nbsp;bề&nbsp;mặt&nbsp;sạch&nbsp;và&nbsp;mềm)&nbsp;hoặc&nbsp;đặt&nbsp;ngửa&nbsp;để&nbsp;tránh&nbsp;trầy&nbsp;xước&nbsp;tròng&nbsp;kính.</span></li></ul><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">5.&nbsp;Kiểm&nbsp;tra&nbsp;và&nbsp;bảo&nbsp;dưỡng&nbsp;định&nbsp;kỳ:</strong></p><ul><li><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Kiểm&nbsp;tra&nbsp;ốc&nbsp;vít:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;Định&nbsp;kỳ&nbsp;kiểm&nbsp;tra&nbsp;các&nbsp;ốc&nbsp;vít&nbsp;ở&nbsp;khớp&nbsp;nối&nbsp;giữa&nbsp;gọng&nbsp;và&nbsp;càng&nbsp;kính.&nbsp;Nếu&nbsp;thấy&nbsp;lỏng,&nbsp;hãy&nbsp;dùng&nbsp;tua&nbsp;vít&nbsp;nhỏ&nbsp;chuyên&nbsp;dụng&nbsp;để&nbsp;siết&nbsp;lại&nbsp;nhẹ&nbsp;nhàng.</span></li><li><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Kiểm&nbsp;tra&nbsp;đệm&nbsp;mũi:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;Với&nbsp;gọng&nbsp;có&nbsp;đệm&nbsp;mũi&nbsp;rời,&nbsp;kiểm&nbsp;tra&nbsp;xem&nbsp;chúng&nbsp;có&nbsp;bị&nbsp;ố&nbsp;vàng,&nbsp;cứng&nbsp;hoặc&nbsp;lỏng&nbsp;không.&nbsp;Nếu&nbsp;có,&nbsp;nên&nbsp;thay&nbsp;thế&nbsp;để&nbsp;đảm&nbsp;bảo&nbsp;thoải&nbsp;mái.</span></li><li><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Mang&nbsp;đến&nbsp;GlassyZone:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;Khoảng&nbsp;6&nbsp;tháng&nbsp;đến&nbsp;1&nbsp;năm&nbsp;một&nbsp;lần&nbsp;(hoặc&nbsp;khi&nbsp;cảm&nbsp;thấy&nbsp;kính&nbsp;bị&nbsp;lỏng,&nbsp;lệch&nbsp;form),&nbsp;bạn&nbsp;nên&nbsp;mang&nbsp;kính&nbsp;đến&nbsp;cửa&nbsp;hàng&nbsp;mắt&nbsp;kính&nbsp;GlassyZone&nbsp;để&nbsp;được&nbsp;điều&nbsp;chỉnh,&nbsp;vệ&nbsp;sinh&nbsp;chuyên&nbsp;sâu&nbsp;bằng&nbsp;sóng&nbsp;siêu&nbsp;âm&nbsp;và&nbsp;kiểm&nbsp;tra&nbsp;tổng&nbsp;thể</span></li></ul>','2026-08-28 10:27:34','2026-08-29 03:27:19'),('0ccffd49-b0cd-44d0-b267-e0357c05f7d9','Tròng kính đánh Nikon Rx AS Viewfit Transitions Gen S 1.50','trong',8180000.00,NULL,10,'<p></p>','2026-08-28 12:18:03','2026-08-28 12:18:03'),('26bc33ec-aa84-42f7-ab51-e1511f2c7118','Gọng kính MACHILA MA5625T 80006','gong',3280000.00,3400000.00,20,'<p></p>','2026-08-28 04:42:41','2026-08-28 10:53:23'),('2893c768-44da-4d58-a8fc-a18ef642b354','Gọng kính PETERSON 33051','gong',1180000.00,NULL,12,'<p></p>','2026-08-28 10:05:45','2026-08-28 10:05:45'),('3096ffcb-c0dd-44b5-9d46-d5e590bb7446','Tròng kính đánh Nikon Rx SeeMax Inifinite Pure Blue UV 1.60','trong',10280000.00,NULL,15,'<p></p>','2026-08-28 12:05:27','2026-08-28 12:05:27'),('40d375cd-e42d-49b9-b59a-04893c40caed','Gọng kính AVERY ELANI','gong',1400000.00,NULL,15,'<p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Gọng&nbsp;kính&nbsp;AVERY&nbsp;ELANI</strong></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Thiết&nbsp;kế&nbsp;dáng&nbsp;</span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">bầu&nbsp;dục</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">&nbsp;với&nbsp;những&nbsp;đường&nbsp;cong&nbsp;mềm&nbsp;mại,&nbsp;phần&nbsp;đuôi&nbsp;hơi&nbsp;xếch&nbsp;nhẹ&nbsp;tạo&nbsp;hiệu&nbsp;ứng&nbsp;mắt&nbsp;mèo&nbsp;tinh&nbsp;tế.&nbsp;Kiểu&nbsp;dáng&nbsp;này&nbsp;giúp&nbsp;gương&nbsp;mặt&nbsp;trông&nbsp;thanh&nbsp;thoát&nbsp;hơn,&nbsp;tôn&nbsp;lên&nbsp;đường&nbsp;nét&nbsp;tự&nbsp;nhiên&nbsp;và&nbsp;mang&nbsp;lại&nbsp;vẻ&nbsp;ngoài&nbsp;trẻ&nbsp;trung,&nbsp;đầy&nbsp;sức&nbsp;sống.</span></p><p></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(9, 3, 2);\">Gọng&nbsp;kính&nbsp;có&nbsp;2&nbsp;màu&nbsp;cực&nbsp;ấn&nbsp;tượng:</span></p><ul><li><s